-- Generated by scripts/places (OHSAA state pages). Inserts MeetPlacings (Place, 0 points, no participant) only where the performance has none. Id-independent; re-runnable.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @pid INT;

-- 2007 OHSAA Division I State Track and Field Championships: Stephanie Foster Pole Vault place 9
SET @pid = (SELECT TOP 1 p.Id FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE a.FirstName+N' '+a.LastName=N'Stephanie Foster' AND a.Gender=2 AND m.Name=N'2007 OHSAA Division I State Track and Field Championships' AND CAST(m.Date AS date)='2007-06-16' AND e.Name=N'Pole Vault' AND e.Gender=2);
IF @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) SELECT MeetId, Id, NULL, 9, 0, 0 FROM Performances WHERE Id=@pid;
-- 2013 OHSAA Division I State Track and Field Championships: Ashley Murray 3200M place 7
SET @pid = (SELECT TOP 1 p.Id FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE a.FirstName+N' '+a.LastName=N'Ashley Murray' AND a.Gender=2 AND m.Name=N'2013 OHSAA Division I State Track and Field Championships' AND CAST(m.Date AS date)='2013-06-07' AND e.Name=N'3200M' AND e.Gender=2);
IF @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) SELECT MeetId, Id, NULL, 7, 0, 0 FROM Performances WHERE Id=@pid;
