IF @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) SELECT MeetId, Id, NULL, 5, 0, 0 FROM Performances WHERE Id=@pid;
